SELECT 
FROM stop_pattern
WHERE line_id = #{lineId}
  AND active = TRUE
  AND valid_from  <=  #{serviceDate}
  AND (
      valid_to IS NULL
      OR valid_to  >=  #{serviceDate}
  )
ORDER BY service_type ASC,
         valid_from DESC,
         provider_pattern_id ASC

SELECT  
FROM stop_pattern
WHERE line_id = #{lineId}
AND provider_pattern_id = #{providerPatternId}
AND valid_from = #{validFrom}

